const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'] as const;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function notAllowed(res: ServerResponse, allowed: string[]): void {
  send(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allowed.join(' or ')}.` } },
    { allow: allowed.join(', ') },
  );
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Validates a parsed body and applies defaults. Returns every offending field, not just the first. */
export function validateCreate(raw: unknown): { ok: true; value: NewJob } | { ok: false; fields: FieldError[] } {
  if (!isPlainObject(raw)) return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  const fields: FieldError[] = [];
  for (const key of Object.keys(raw)) {
    if (!(ALLOWED_FIELDS as readonly string[]).includes(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  if (!Object.hasOwn(raw, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof raw.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (raw.input.length < 1 || raw.input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (raw.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = raw.input;
  }

  const integer = (name: 'steps' | 'failAttempts', min: number, max: number, dflt: number): number => {
    if (!Object.hasOwn(raw, name)) return dflt;
    const v = raw[name];
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
      return dflt;
    }
    return v;
  };
  const steps = integer('steps', 1, 20, 5);
  const failAttempts = integer('failAttempts', 0, 5, 0);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const text = await readBody(req);
  const fields: FieldError[] = [];

  const contentType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = contentType === 'application/json';
  if (!isJson) fields.push({ field: 'body', message: 'Content-Type must be application/json' });

  let key: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    const k = String(keyHeader);
    if (IDEMPOTENCY_KEY.test(k)) key = k;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsedValue: NewJob | undefined;
  if (tooLarge) {
    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (isJson) {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(text);
      parsedOk = true;
    } catch {
      fields.push({ field: 'body', message: 'must be valid JSON' });
    }
    if (parsedOk) {
      const result = validateCreate(parsed);
      if (result.ok) parsedValue = result.value;
      else fields.push(...result.fields);
    }
  }

  const value = parsedValue;
  if (fields.length > 0 || value === undefined) {
    const message = `Invalid request: ${fields.map((f) => `${f.field} ${f.message}`).join('; ')}.`;
    return sendError(res, 400, 'invalid_request', message, fields);
  }

  const payload = JSON.stringify([value.input, value.steps, value.failAttempts]);
  const outcome = inTransaction(db, () => {
    if (key !== null) {
      const existing = findByIdempotencyKey(db, key);
      if (existing) {
        return existing.payload === payload ? { status: 200 as const, job: existing } : { status: 409 as const, job: undefined };
      }
    }
    return { status: 201 as const, job: insertJob(db, value, key, payload) };
  });

  if (outcome.job === undefined) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, toJson(outcome.job));
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});
server.listen(Number(process.env.PORT ?? 3000), () => {
  console.log(`server listening on ${process.env.PORT ?? 3000}`);
});

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/health') {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: workerIsUp(db, Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJson) });
    if (method === 'POST') return createJob(req, res);
    return notAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return notAllowed(res, ['GET']);
    const row = getJob(db, match[1]!);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, toJson(row));
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
    setTimeout(() => process.exit(0), 2000).unref();
  });
}

