// Numeric text is sent as a number; anything else is sent as typed so the API's validation reports it.
function toApiValue(raw) {
  const t = raw.trim();
  return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : raw;
}

input.new_string:
// A number field's value is sent as a number (valueAsNumber also handles forms like "1e1");
// anything that is not a finite number is sent as typed so the API's validation reports it.
function toApiValue(el) {
  const n = el.valueAsNumber;
  return Number.isFinite(n) ? n : el.value;
}

